window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-687d021066b818b9"]={"versions": [{"id": "FIG-687d021066b818b9", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles dreidimensionales Koordinatensystem / Vektorraum-Diagramm zur Veranschaulichung des Filter- und Sichtenansatzes (View Approach) im AUTOSAR Generic Structure Template (GST). Das Diagramm visualisiert die drei orthogonalen Dimensionen zur Selektion, Dokumentation und Filterung von Modell- und Dokumentinhalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei orthogonale Achsen mit ihren Modellierungsmechanismen und Wertebereichen dar:</p>\n<ul class=\"fig-list\"><li>Vertikale Achse (Z-Richtung): <code>LanguageSpecific</code> mit dem Datentyp <code>(LEnum)</code> und beispielhaften Sprachwerten <code>en</code> und <code>de</code>.\n</li><li>Horizontale Achse nach rechts (X-Richtung): <code>DocumentViewSelectable</code> mit Identifikatoren vom Typ <code>(ViewToken)</code>.\n</li><li>Räumliche Tiefenachse (Y-Richtung): <code>atpVariation</code> gesteuert über Systemkonstanten <code>(SW-SYSTEMCONST)</code> mit beispielhaften Ausprägungen <code>Country</code> (<code>1</code>, <code>2</code>).\n</li></ul>\n<p class=\"fig-p\">Eine aufgespannte Gitterebene (gestrichelt und punktiert) schneidet die Achsen und illustriert konkrete Schnittmengen (Filterkriterien) anhand von Attributwerten wie <code>DETAILED</code> und <code>INTERNAL</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische multidimensionale Projektion. Zur Laufzeit bzw. Dokumentengenerierung und Modellverarbeitung (z. B. View Filtering oder Variantenauflösung) wird ein Filterpunkt oder Filtervektor im dreidimensionalen Raum definiert: Durch Auswahl der Sprache (<code>LEnum</code>), Dokumentensicht (<code>ViewToken</code>) und Variantenbelegung (<code>SW-SYSTEMCONST</code>) wird eine eindeutige Projektion auf den relevanten Teilbestand des AUTOSAR-Modells bzw. Dokuments selektiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterung des integrativen Zusammenspiels dreier orthogonaler Filterkonzepte in AUTOSAR GST: Mehrsprachigkeit (<code>LanguageSpecific</code>), Dokumentensichten (<code>DocumentViewSelectable</code>) und Variabilitätsauflösung (<code>atpVariation</code>). Modellierer und Tool-Entwickler müssen beachten, dass diese drei Mechanismen unabhängig voneinander kombiniert werden können, um zielgruppenspezifische Sichten auf Systembeschreibungen zu erzeugen.</p>"}, {"id": "FIG-c9897eb3fa809d8a", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles dreidimensionales Koordinatensystem / Vektorraum-Diagramm zur Veranschaulichung des Filter- und Sichtenansatzes (View Approach) im AUTOSAR Generic Structure Template (GST). Das Diagramm visualisiert die drei orthogonalen Dimensionen zur Selektion, Dokumentation und Filterung von Modell- und Dokumentinhalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt drei orthogonale Achsen mit ihren Modellierungsmechanismen und Wertebereichen dar:</p>\n<ul class=\"fig-list\"><li>Vertikale Achse (Z-Richtung): <code>LanguageSpecific</code> mit dem Datentyp <code>(LEnum)</code> und beispielhaften Sprachwerten <code>en</code> und <code>de</code>.\n</li><li>Horizontale Achse nach rechts (X-Richtung): <code>DocumentViewSelectable</code> mit Identifikatoren vom Typ <code>(ViewToken)</code>.\n</li><li>Räumliche Tiefenachse (Y-Richtung): <code>atpVariation</code> gesteuert über Systemkonstanten <code>(SW-SYSTEMCONST)</code> mit beispielhaften Ausprägungen <code>Country</code> (<code>1</code>, <code>2</code>).\n</li></ul>\n<p class=\"fig-p\">Eine aufgespannte Gitterebene (gestrichelt und punktiert) schneidet die Achsen und illustriert konkrete Schnittmengen (Filterkriterien) anhand von Attributwerten wie <code>DETAILED</code> und <code>INTERNAL</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische multidimensionale Projektion. Zur Laufzeit bzw. Dokumentengenerierung und Modellverarbeitung (z. B. View Filtering oder Variantenauflösung) wird ein Filterpunkt oder Filtervektor im dreidimensionalen Raum definiert: Durch Auswahl der Sprache (<code>LEnum</code>), Dokumentensicht (<code>ViewToken</code>) und Variantenbelegung (<code>SW-SYSTEMCONST</code>) wird eine eindeutige Projektion auf den relevanten Teilbestand des AUTOSAR-Modells bzw. Dokuments selektiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterung des integrativen Zusammenspiels dreier orthogonaler Filterkonzepte in AUTOSAR GST: Mehrsprachigkeit (<code>LanguageSpecific</code>), Dokumentensichten (<code>DocumentViewSelectable</code>) und Variabilitätsauflösung (<code>atpVariation</code>). Modellierer und Tool-Entwickler müssen beachten, dass diese drei Mechanismen unabhängig voneinander kombiniert werden können, um zielgruppenspezifische Sichten auf Systembeschreibungen zu erzeugen.</p>"}], "trans": [{"from": "FIG-687d021066b818b9", "to": "FIG-c9897eb3fa809d8a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
